import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    cost = [int(x) for x in data[1:n + 1]]
    mask_of = [1 << i for i in range(n)]
    pos = n + 1
    for _ in range(n - 1):
        u = int(data[pos]) - 1
        v = int(data[pos + 1]) - 1
        pos += 2
        mask_of[u] |= 1 << v
        mask_of[v] |= 1 << u
    best = None
    for mask in range(1, 1 << n):
        ok = True
        for v in range(n):
            if not mask & mask_of[v]:
                ok = False
                break
        if not ok:
            continue
        total = 0
        for v in range(n):
            if mask >> v & 1:
                total += cost[v]
        if best is None or total < best:
            best = total
    print(best)


main()
